WITH lp AS ( SELECT cr, pack_id FROM cr_in_pack UNION SELECT cr, pack_id FROM pack_member ), ls AS ( SELECT cr, section_id FROM cr_modifies_section UNION SELECT cr, section_id FROM section_modified_by ), dk AS ( SELECT id AS doc_id, id AS k FROM document UNION SELECT id AS doc_id, number AS k FROM document WHERE number IS NOT NULL ), pk AS ( SELECT id AS pid, id AS k FROM cr_pack UNION SELECT id AS pid, pack_number AS k FROM cr_pack WHERE pack_number IS NOT NULL ), docs AS ( SELECT id AS doc_id, COALESCE(number, id) AS docnum, CAST(ltrim(replace(replace(replace(replace(replace(upper(trim(target_release)), 'RELEASE', ''), 'REL', ''), '-', ''), ' ', ''), '_', ''), 'RV.') AS INTEGER) AS trel FROM document ), cp_map AS ( SELECT DISTINCT dk.doc_id AS doc_id, pk.pid AS pid FROM lp JOIN dk ON dk.k = lp.cr JOIN pk ON pk.k = lp.pack_id ), cs_map AS ( SELECT DISTINCT dk.doc_id AS doc_id, s.spec AS spec, s.clause AS clause, CAST(ltrim(replace(replace(replace(replace(replace(upper(trim(s."release")), 'RELEASE', ''), 'REL', ''), '-', ''), ' ', ''), '_', ''), 'RV.') AS INTEGER) AS rel FROM ls JOIN dk ON dk.k = ls.cr JOIN section s ON s.id = ls.section_id ), gd AS ( SELECT DISTINCT dk.doc_id AS doc_id, disp.code AS code, m.label AS wg_label FROM disposition disp JOIN dk ON dk.k = disp.target JOIN resolution r ON r.id = disp.resolution_id JOIN meeting m ON m.id = r.meeting_id WHERE (replace(replace(replace(lower(trim(disp.evidence_status)), '_', ''), '-', ''), ' ', '') LIKE '%sourceverified%' OR replace(replace(replace(lower(trim(disp.evidence_status)), '_', ''), '-', ''), ' ', '') IN ('verifiedsource', 'verifiedfromsource', 'verifiedagainstsource')) AND replace(replace(replace(lower(trim(disp.evidence_status)), '_', ''), '-', ''), ' ', '') NOT LIKE '%not%' AND replace(replace(replace(lower(trim(disp.evidence_status)), '_', ''), '-', ''), ' ', '') NOT LIKE '%unverified%' AND replace(replace(replace(lower(trim(disp.scope)), '_', ''), '-', ''), ' ', '') IN ('document', 'wholedocument', 'whole', 'wholedoc', 'fulldocument', 'full', 'entiredocument', 'entire', 'doc') AND (replace(replace(replace(upper(trim(m.wg)), '_', ''), '-', ''), ' ', '') LIKE '%RAN3%' OR replace(replace(replace(upper(trim(m.wg)), '_', ''), '-', ''), ' ', '') LIKE '%RANWG3%' OR replace(replace(replace(upper(trim(m.wg)), '_', ''), '-', ''), ' ', '') IN ('R3', 'WG3')) ), target_pack AS ( SELECT id AS pid, tsg_number AS tnum FROM cr_pack WHERE pack_number = '{ANCHOR}' OR id = '{ANCHOR}' ), cand AS ( SELECT DISTINCT d.doc_id AS doc_id, d.docnum AS docnum, cs.spec AS spec, cs.clause AS clause, cs.rel AS rel, tp.tnum AS tnum FROM target_pack tp JOIN cp_map cm ON cm.pid = tp.pid JOIN docs d ON d.doc_id = cm.doc_id JOIN cs_map cs ON cs.doc_id = d.doc_id AND cs.rel = d.trel WHERE d.trel IN (18) AND EXISTS (SELECT 1 FROM gd WHERE gd.doc_id = d.doc_id) ), cc AS ( SELECT DISTINCT spec, clause, rel, tnum FROM cand ), other_packs AS ( SELECT DISTINCT cs2.spec AS spec, cs2.clause AS clause, cs2.rel AS rel, p2.tsg_number AS pnum, COALESCE(p2.pack_number, p2.id) AS pack_number, p2.tsg_meeting AS tsg_meeting FROM (SELECT DISTINCT spec, clause, rel FROM cand) k JOIN cs_map cs2 ON cs2.spec = k.spec AND cs2.clause = k.clause AND cs2.rel = k.rel JOIN docs d2 ON d2.doc_id = cs2.doc_id AND d2.trel = cs2.rel JOIN cp_map cm2 ON cm2.doc_id = d2.doc_id JOIN cr_pack p2 ON p2.id = cm2.pid ) SELECT DISTINCT c.docnum AS document, c.spec AS specification, c.clause AS clause FROM cand c WHERE NOT EXISTS ( SELECT 1 FROM other_packs e WHERE e.spec = c.spec AND e.clause = c.clause AND e.rel = c.rel AND e.pnum < c.tnum )
